sealed class BallItem : GameItem {
    internal BallThread Twin { get; set; } = null!;   // internal: pair stays in-module
    public override void Draw() { ... }
    public void Move()          { ... }
    public override void Click() => Twin.ToggleSuspend();
}
sealed class BallThread : ThreadBase {
    internal BallItem Twin { get; set; } = null!;
    protected override void Tick() { if (!suspended) { Twin.Draw(); Twin.Move(); } }
}
static BallItem CreateBall() {                        // factory wires both ends
    var item = new BallItem(); var driver = new BallThread();
    item.Twin = driver; driver.Twin = item; return item;
}

