public interface ISuspendable {                 // capability with default behaviour
    bool Suspended { get; set; }
    void Toggle() => Suspended = !Suspended;
}

public sealed class BallItem : GameItem, ISuspendable {   // one object, no twin link
    public bool Suspended { get; set; }
    public override void Click() => Toggle();
}
